command:
const rollToCard = game.pirateborg.api.grants.rollToCard;

const hp = actor.system.attributes.hp;
if (hp.value >= hp.max) {
  ui.notifications?.info?.(`${actor.name} is already at full HP.`);
  return;
}

// d6 if Buccan Cook was taken twice, otherwise d4 (single source of truth: the
// feature's quantity). Count across every copy so it works whether the takes are
// stacked (quantity 2) or held as two separate items.
const cookCount = actor.items
  .filter((i) => i.type === "feature" && i.name === "Buccan Cook")
  .reduce((total, i) => total + (i.system.quantity || 1), 0);
const die = cookCount >= 2 ? "1d6" : "1d4";

// Decrement first so the card can report the rations remaining after this meal.
const remaining = (item.system.quantity || 1) - 1;
if (remaining > 0) {
  await item.update({ "system.quantity": remaining });
} else {
  await item.delete();
}

const { total } = await rollToCard(actor, {
  formula: die,
  formulaLabel: `${die} HP`,
  title: `Eat ${item.name}`,
  outcomeTitle: (n) => `+${Math.min(hp.max - hp.value, Math.max(0, n))} HP`,
  description: (n) => {
    const healed = Math.min(hp.max - hp.value, Math.max(0, n));
    return `Recovered ${healed} HP. ${Math.max(0, remaining)} ration${remaining === 1 ? "" : "s"} left.`;
  },
});

const healed = Math.min(hp.max - hp.value, Math.max(0, total));
await actor.update({ "system.attributes.hp.value": hp.value + healed });
